import{_ as t,o,c as n,a2 as s}from"./chunks/framework.1C62pOns.js";const a="/pro-agent-hub-installer/capturas/en/fontes-detalhe.png",r="/pro-agent-hub-installer/capturas/en/conhecimento-detalhe.png",m=JSON.parse('{"title":"Knowledge and data sources","description":"","frontmatter":{},"headers":[],"relativePath":"en/interface/conhecimento.md","filePath":"en/interface/conhecimento.md","lastUpdated":1787856241000}'),i={name:"en/interface/conhecimento.md"};function c(l,e,d,h,p,u){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="knowledge-and-data-sources" tabindex="-1">Knowledge and data sources <a class="header-anchor" href="#knowledge-and-data-sources" aria-label="Permalink to &quot;Knowledge and data sources&quot;">​</a></h1><p>An agent knows what the model learned, and nothing else. <strong>Knowledge</strong> is how you give it what your company knows.</p><p>There are two pieces, and the order matters: the <strong>data source</strong> says where the content comes from; the <strong>knowledge base</strong> turns that content into vectors the agent can search.</p><h2 id="data-sources" tabindex="-1">Data sources <a class="header-anchor" href="#data-sources" aria-label="Permalink to &quot;Data sources&quot;">​</a></h2><p><img src="'+a+'" alt="fontes-detalhe"></p><p>There are three types, and the screen changes with the one you pick:</p><p><strong>Database (SQL).</strong> A registered connection plus a query. Each row of the result becomes a document.</p><p><strong>File folder.</strong> A directory on the server, optionally recursive, filtered by extension. Reads <code>pdf</code>, <code>docx</code>, <code>txt</code>, <code>csv</code>, among others.</p><p><strong>Website (web scraping).</strong> A URL plus <strong>CSS selectors</strong> saying which piece of the page is which field. HTTP headers are optional — the <code>User-Agent</code> comes pre-filled, because without one many sites refuse the connection.</p><div class="tip custom-block"><p class="custom-block-title">Don&#39;t know the selectors?</p><p>The <strong>Suggest</strong> button calls Pegasus: it fetches the page&#39;s real HTML and proposes the selectors. It is the step nobody can guess without opening the browser inspector. Requires Pegasus enabled in Settings.</p></div><div class="warning custom-block"><p class="custom-block-title">Pages that build their content in JavaScript are out</p><p>The capture reads the served HTML, with no browser. If the content only appears after JavaScript runs, the selectors find nothing. It is the trade accepted so as not to carry a Chromium inside the container.</p></div><p>The capture has caps of its own — total time, body size, number of redirects and 5,000 rows. A website is a third party&#39;s: without caps, a slow or enormous page would hold the process hostage.</p><p><strong>Test</strong> runs the collection and shows what came back, writing nothing. Use it before linking the source to a knowledge base.</p><h2 id="knowledge" tabindex="-1">Knowledge <a class="header-anchor" href="#knowledge" aria-label="Permalink to &quot;Knowledge&quot;">​</a></h2><p><img src="'+r+'" alt="conhecimento-detalhe"></p><p>A knowledge base points at a data source and at an <strong>embedding model</strong>, and produces a collection of vectors.</p><h3 id="processing-tab" tabindex="-1">Processing tab <a class="header-anchor" href="#processing-tab" aria-label="Permalink to &quot;Processing tab&quot;">​</a></h3><p>The vectorisation parameters live here:</p><ul><li><strong>Chunk size and overlap</strong> — documents bigger than the chunk are split; the overlap keeps a sentence from being cut in half between two chunks.</li><li><strong>Batch size</strong> — how many documents go to the embedding model at a time.</li><li><strong>Maximum search results</strong> — how many excerpts the agent gets per question.</li><li><strong>Cron expression</strong> — to re-vectorise on its own, on a schedule.</li></ul><p>Plus three Python fields, which apply to the <strong>SQL</strong> source:</p><ul><li><strong>Pipeline declaration</strong> — runs once, before ingestion. This is where <code>import</code> statements, helper functions and accumulators go.</li><li><strong>Document content</strong> — an expression returning the text to vectorise.</li><li><strong>Document metadata</strong> — an expression returning a dictionary.</li></ul><div class="warning custom-block"><p class="custom-block-title">These expressions run in an empty scope</p><p>No platform function exists there. What you have is <code>row</code>, the current query row, and whatever you defined yourself in the Pipeline declaration. See <a href="/pro-agent-hub-installer/en/funcoes/conhecimento_pipeline">Knowledge — pipeline expressions</a>.</p></div><h3 id="full-reload" tabindex="-1">Full reload <a class="header-anchor" href="#full-reload" aria-label="Permalink to &quot;Full reload&quot;">​</a></h3><p>A full reload <strong>drops the collection and recreates it</strong>. That is what you want when you changed the embedding model (the dimension changes) or when records were deleted at the source and stale vectors were left behind. A normal load only adds what changed.</p>',24)])])}const w=t(i,[["render",c]]);export{m as __pageData,w as default};
